INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Löschung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt Art. 17 DSGVO Betroffenen das Recht, die Löschung ihrer personenbezogenen Daten zu verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 17 DSGVO garantiert das Recht auf Löschung"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Löschung auch als „Recht auf Vergessenwerden“ bezeichnet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 17 DSGVO umfasst das Recht auf Vergessenwerden"}, {"text": "Nein", "correct": false, "because": "Begriff ist etabliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen das Recht auf Löschung immer erfüllen, unabhängig von gesetzlichen Aufbewahrungspflichten?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzliche Pflichten können Vorrang haben"}, {"text": "Ja", "correct": false, "because": "Ausnahmen sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene ihr Recht auf Löschung ausüben, wenn die Daten für den ursprünglichen Zweck nicht mehr erforderlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 17 Abs. 1a DSGVO erlaubt dies"}, {"text": "Nein", "correct": false, "because": "Zweckentfall ist Löschungsgrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Löschung gemäß Art. 17 DSGVO kostenpflichtig für Betroffene?', 2, '[{"text": "Nein", "correct": true, "because": "Art. 12 Abs. 5 DSGVO schreibt Kostenfreiheit vor"}, {"text": "Ja", "correct": false, "because": "Kostenfreiheit ist Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was erlaubt das Recht auf Löschung gemäß Art. 17 DSGVO Betroffenen?', 2, '[{"text": "Entfernung ihrer personenbezogenen Daten", "correct": true, "because": "Art. 17 DSGVO definiert dies"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um ein Löschungsverlangen nach Art. 17 DSGVO zu erfüllen?', 3, '[{"text": "Einen Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO setzt eine Monatsfrist"}, {"text": "Drei Monate", "correct": false, "because": "Zu lang"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund berechtigt Betroffene zur Ausübung des Rechts auf Löschung?', 2, '[{"text": "Daten sind für den Zweck nicht mehr notwendig", "correct": true, "because": "Art. 17 Abs. 1a DSGVO nennt dies"}, {"text": "Daten wurden korrekt verarbeitet", "correct": false, "because": "Kein Löschungsgrund"}, {"text": "Daten sind öffentlich", "correct": false, "because": "Nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausnahme kann die Löschung gemäß Art. 17 DSGVO verhindern?', 2, '[{"text": "Gesetzliche Aufbewahrungspflichten", "correct": true, "because": "Art. 17 Abs. 3b DSGVO nennt dies"}, {"text": "Technische Schwierigkeiten", "correct": false, "because": "Keine Ausnahme"}, {"text": "Interne Unternehmenspolitik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme müssen Unternehmen nach einem Löschungsverlangen ergreifen?', 2, '[{"text": "Daten löschen oder Löschung begründen", "correct": true, "because": "Pflicht nach Art. 17 DSGVO"}, {"text": "Daten weiter speichern", "correct": false, "because": "Verstoß gegen Recht"}, {"text": "Daten archivieren", "correct": false, "because": "Nur bei Ausnahme zulässig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Gründe berechtigen Betroffene zur Ausübung des Rechts auf Löschung nach Art. 17 DSGVO?', 4, '[{"text": "Daten sind nicht mehr notwendig", "correct": true, "because": "Art. 17 Abs. 1a"}, {"text": "Einwilligung wurde widerrufen", "correct": true, "because": "Art. 17 Abs. 1b"}, {"text": "Daten wurden unrechtmäßig verarbeitet", "correct": true, "because": "Art. 17 Abs. 1d"}, {"text": "Daten sind noch zweckmäßig", "correct": false, "because": "Kein Löschungsgrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen müssen Unternehmen bei einem Löschungsverlangen ergreifen?', 3, '[{"text": "Daten löschen", "correct": true, "because": "Pflicht nach Art. 17"}, {"text": "Dritte informieren", "correct": true, "because": "Art. 17 Abs. 2 bei Weitergabe"}, {"text": "Verweigerung begründen", "correct": true, "because": "Bei Ausnahmen erforderlich"}, {"text": "Daten ignorieren", "correct": false, "because": "Verstoß gegen DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausnahmen können das Recht auf Löschung einschränken?', 4, '[{"text": "Gesetzliche Aufbewahrungspflichten", "correct": true, "because": "Art. 17 Abs. 3b"}, {"text": "Öffentliches Interesse", "correct": true, "because": "Art. 17 Abs. 3c"}, {"text": "Rechtsansprüche", "correct": true, "because": "Art. 17 Abs. 3e"}, {"text": "Technische Präferenzen", "correct": false, "because": "Keine Ausnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Löschung haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 17 strafbar"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen Unternehmen bei einem Löschungsverlangen bereitstellen?', 3, '[{"text": "Bestätigung der Löschung", "correct": true, "because": "Pflicht nach Art. 12"}, {"text": "Gründe für Verweigerung", "correct": true, "because": "Bei Ausnahmen erforderlich"}, {"text": "Frist für Löschung", "correct": true, "because": "Transparenz über Bearbeitung"}, {"text": "Softwareversion", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Löschung erlaubt die Entfernung unnötiger Daten. b) Es gilt nur bei unrechtmäßiger Verarbeitung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unnötige Daten ja, mehrere Gründe möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen Löschungsverlangen innerhalb eines Monats erfüllen. b) Gesetzliche Pflichten können Löschung verhindern.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Frist und Ausnahmen korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Betroffene können kostenfrei Löschung verlangen. b) Unternehmen dürfen immer Gründe zur Verweigerung verschweigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenfrei ja, Begründung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Das Recht auf Löschung gilt bei Widerruf der Einwilligung. b) Dritte müssen nicht informiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Widerruf ja, Dritte bei Weitergabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße gegen das Recht auf Löschung können Bußgelder nach sich ziehen. b) Es gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, alle Daten betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

